  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  max-width: 1333px;
  margin: 0 auto var(--jk-space-4);
  gap: var(--jk-space-4);
}

.workspace-header h1,
.workspace-header p,
.panel h2,
.panel h3,
.panel p,
.panel dl,
.panel ul,
.panel ol {
  margin-top: 0;
}

.workspace-header h1 {
  margin-bottom: var(--jk-space-2);
  font-size: 1.625rem;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.section-kicker {
  margin-bottom: var(--jk-space-2);
  color: var(--jk-color-muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.workspace-intro,
.helper-copy,
.choice-description,
.control-help,
.case-state,
.metadata dt {
  color: var(--jk-color-muted);
}

.workspace-intro {
  margin-bottom: 0;
}

.header-status {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--jk-space-2);
}

.header-status span {
  min-height: 32px;
  padding: var(--jk-space-2) var(--jk-space-3);
  background: var(--jk-color-surface);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  white-space: nowrap;
}

.workspace-grid {
  display: grid;
  grid-template-columns: minmax(210px, 240px) minmax(380px, 1fr) minmax(560px, 620px);
  align-items: start;
  max-width: 1333px;
  margin: 0 auto;
  gap: var(--jk-space-4);
}

.panel {
  min-width: 0;
  overflow: hidden;
  background: var(--jk-color-surface);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-panel);
}

.panel-heading,
.panel-section,
.decision-body {
  padding: var(--jk-space-4);
}

.panel-heading {
  border-bottom: 1px solid var(--jk-color-border);
}

.panel-heading-row,
.section-heading-row,
.selected-heading-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--jk-space-3);
}

.panel-heading h2,
.section-heading-row h3,
.selected-heading-row h2 {
  margin-bottom: var(--jk-space-2);
}

.panel-heading h2,
.section-heading-row h3 {
  font-size: 1rem;
  line-height: 1.3;
}

.panel-heading p,
.section-heading-row p,
.selected-heading-row p {
  margin-bottom: 0;
}

.queue-count,
.evidence-count {
  flex: 0 0 auto;
  color: var(--jk-color-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.queue-control {
  display: grid;
  margin-top: var(--jk-space-3);
  gap: var(--jk-space-2);
}

.queue-control label {
  font-size: 0.8125rem;
  font-weight: 700;
}

.queue-control select {
  width: 100%;
  min-height: 44px;
  padding: 0 var(--jk-space-3);
  background: var(--jk-color-surface);
  border: 1px solid var(--jk-color-muted);
  border-radius: var(--jk-radius-control);
}

.case-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.case-list li + li {
  border-top: 1px solid var(--jk-color-border);
}

.case-card {
  display: grid;
  width: 100%;
  min-height: 96px;
  padding: var(--jk-space-3) var(--jk-space-4);
  background: var(--jk-color-surface);
  border: 0;
  border-left: 4px solid var(--jk-color-surface);
  border-radius: 0;
  text-align: left;
  cursor: pointer;
  gap: var(--jk-space-2);
  overflow-wrap: anywhere;
}

.case-card:hover {
  background: var(--jk-color-canvas);
}

.case-card[aria-current="true"] {
  background: var(--jk-color-canvas);
  border-left-color: var(--jk-color-focus);
}

.case-topline,
.case-name-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--jk-space-2);
}

.case-id,
.case-amount,
.metadata dd {
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-variant-numeric: tabular-nums;
}

.case-id,
.case-amount,
.case-customer {
  font-weight: 700;
}

.case-state {
  font-size: 0.8125rem;
}

.case-card[aria-current="true"] .case-state {
  color: var(--jk-color-warning);
  font-weight: 700;
}

.selected-label {
  color: var(--jk-color-focus);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.state-message {
  display: none;
  min-height: 140px;
  padding: var(--jk-space-4);
  align-content: center;
  gap: var(--jk-space-2);
  border-top: 1px solid var(--jk-color-border);
}

.state-message strong,
.state-message span {
  display: block;
}

.refund-workspace[data-state="empty"] .empty-state,
.refund-workspace[data-state="loading"] .loading-state,
.refund-workspace[data-state="error"] .error-state {
  display: grid;
}

.refund-workspace[data-state="empty"] .case-list,
.refund-workspace[data-state="loading"] .case-list,
.refund-workspace[data-state="error"] .case-list {
  display: none;
}

.loading-state {
  color: var(--jk-color-focus);
}

.error-state {
  color: var(--jk-color-risk);
}

.selected-request {
  padding: var(--jk-space-4);
}

.selected-heading-row {
  padding-bottom: var(--jk-space-4);
  border-bottom: 1px solid var(--jk-color-border);
}

.selected-heading-row h2 {
  font-size: 1.25rem;
  line-height: 1.25;
}

.status-badge {
  flex: 0 0 auto;
  padding: var(--jk-space-2) var(--jk-space-3);
  color: var(--jk-color-warning);
  background: var(--jk-color-surface);
  border: 1px solid var(--jk-color-warning);
  border-radius: var(--jk-radius-control);
  font-size: 0.75rem;
  font-weight: 700;
  white-space: nowrap;
}

.metadata {
  display: grid;
  grid-template-columns: minmax(0, 0.65fr) minmax(0, 1fr);
  margin-bottom: 0;
  padding: var(--jk-space-4) 0;
  gap: var(--jk-space-3) var(--jk-space-4);
}

.metadata div {
  min-width: 0;
}

.metadata .request-summary {
  grid-column: 1 / -1;
}

.metadata dt {
  margin-bottom: var(--jk-space-2);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.metadata dd {
  margin: 0;
  overflow-wrap: anywhere;
}

.content-section {
  padding-top: var(--jk-space-4);
  border-top: 1px solid var(--jk-color-border);
}

.content-section + .content-section {
  margin-top: var(--jk-space-4);
}

.evidence-list {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
  gap: var(--jk-space-2);
}

.evidence-item {
  display: grid;
  grid-template-columns: 84px minmax(0, 1fr);
  align-items: start;
  min-width: 0;
  padding: var(--jk-space-3);
  background: var(--jk-color-surface);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  gap: var(--jk-space-3);
}

.evidence-item strong,
.evidence-item p {
  display: block;
}

.evidence-item p {
  margin-bottom: 0;
  color: var(--jk-color-muted);
  overflow-wrap: anywhere;
}

.evidence-status {
  color: var(--jk-color-success);
  font-size: 0.75rem;
  font-weight: 700;
}

.evidence-item[data-evidence="missing"] {
  border-color: var(--jk-color-warning);
}

.evidence-item[data-evidence="missing"] .evidence-status {
  color: var(--jk-color-warning);
}

.policy-block {
  padding: var(--jk-space-3) var(--jk-space-4);
  background: var(--jk-color-canvas);
  border-left: 3px solid var(--jk-color-focus);
  border-radius: var(--jk-radius-control);
}

.policy-block h3 {
  margin-bottom: var(--jk-space-2);
  font-size: 1rem;
}

.policy-block p:last-child {
  margin-bottom: 0;
}

.decision-body {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(300px, 1.1fr);
  align-items: start;
  gap: var(--jk-space-4);
}

.decision-group {
  display: grid;
  gap: var(--jk-space-2);
}

.decision-group .helper-copy {
  margin-bottom: var(--jk-space-2);
}

.decision-choice {
  display: grid;
  width: 100%;
  min-height: 58px;
  padding: var(--jk-space-3);
  background: var(--jk-color-surface);
  border: 1px solid var(--jk-color-muted);
  border-radius: var(--jk-radius-control);
  text-align: left;
  cursor: pointer;
  gap: var(--jk-space-2);
  overflow-wrap: anywhere;
}

.decision-choice:hover:not(:disabled) {
  border-color: var(--jk-color-focus);
}

.decision-choice[aria-pressed="true"] {
  background: var(--jk-color-canvas);
  border-color: var(--jk-color-focus);
  border-left-width: 4px;
}

.choice-title-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--jk-space-2);
}

.choice-title {
  font-weight: 700;
}

.choice-selected {
  color: var(--jk-color-focus);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.decision-choice:disabled,
button:disabled,
select:disabled,
textarea:disabled {
  color: var(--jk-color-disabled);
  background: var(--jk-color-canvas);
  border-color: var(--jk-color-disabled);
  cursor: not-allowed;
}

.handoff-section {
  padding-top: 0;
  padding-left: var(--jk-space-4);
  border-top: 0;
  border-left: 1px solid var(--jk-color-border);
}

.handoff-section h2 {
  margin-bottom: var(--jk-space-2);
  font-size: 1rem;
}

.handoff-intro {
  margin-bottom: var(--jk-space-4);
  color: var(--jk-color-muted);
}

.handoff-form,
.control-block {
  display: grid;
}

.handoff-form {
  gap: var(--jk-space-4);
}

.control-block {
  gap: var(--jk-space-2);
}

.control-block label {
  font-weight: 700;
}

.control-block select,
.control-block textarea {
  width: 100%;
  background: var(--jk-color-surface);
  border: 1px solid var(--jk-color-muted);
  border-radius: var(--jk-radius-control);
}

.control-block select {
  min-height: 44px;
  padding: 0 var(--jk-space-3);
}

.control-block textarea {
  min-height: 104px;
  padding: var(--jk-space-3);
  line-height: 1.45;
  resize: vertical;
}

.control-help {
  margin-bottom: 0;
  font-size: 0.8125rem;
}

.control-block [aria-invalid="true"] {
  border-color: var(--jk-color-risk);
}

.error-message {
  color: var(--jk-color-risk);
  font-weight: 700;
}

.handoff-ready {
  display: grid;
  padding: var(--jk-space-3);
  color: var(--jk-color-receipt);
  background: var(--jk-color-surface);
  border: 1px solid var(--jk-color-receipt);
  border-radius: var(--jk-radius-control);
  gap: var(--jk-space-2);
}

.handoff-ready span {
  color: var(--jk-color-text);
}

.send-button {
  min-height: 48px;
  padding: var(--jk-space-3) var(--jk-space-4);
  color: var(--jk-color-surface);
  background: var(--jk-color-receipt);
  border: 1px solid var(--jk-color-receipt);
  border-radius: var(--jk-radius-control);
  font-weight: 700;
  cursor: pointer;
}

.refund-workspace button:focus-visible,
.refund-workspace select:focus-visible,
.refund-workspace textarea:focus-visible {
  outline: 2px solid var(--jk-color-focus);
  outline-offset: 2px;
  box-shadow: var(--jk-focus-ring);
}

.refund-workspace[aria-busy="true"] {
  cursor: progress;
}

@media (max-width: 1160px) {
  .workspace-grid {
    grid-template-columns: minmax(220px, 280px) minmax(0, 1fr);
  }

  .decision-panel {
    grid-column: 1 / -1;
  }

  .decision-body {
    grid-template-columns: minmax(0, 1fr) minmax(320px, 0.9fr);
    align-items: start;
  }

  .handoff-section {
    padding-top: 0;
    padding-left: var(--jk-space-4);
    border-top: 0;
    border-left: 1px solid var(--jk-color-border);
  }
}

@media (max-width: 760px) {
  .refund-workspace {
    padding: var(--jk-space-3);
  }

  .workspace-header,
  .panel-heading-row,
  .section-heading-row,
  .selected-heading-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .header-status {
    justify-content: flex-start;
  }

  .workspace-grid,
  .decision-body {
    grid-template-columns: 1fr;
  }

  .decision-panel {
    grid-column: auto;
  }

  .handoff-section {
    padding-top: var(--jk-space-4);
    padding-left: 0;
    border-top: 1px solid var(--jk-color-border);
    border-left: 0;
  }

  .metadata,
  .evidence-item {
    grid-template-columns: 1fr;
  }

  .metadata .request-summary {
    grid-column: auto;
  }

  .status-badge,
  .queue-count,
  .evidence-count {
    white-space: normal;
  }
}

