  <header class="workspace-header">
    <div>
      <p class="section-kicker">Support operations</p>
      <h1 id="refund-review-title">Refund escalation review</h1>
      <p class="workspace-intro">Review the evidence, choose the next path, and send a clear handoff.</p>
    </div>
    <div class="header-status" aria-label="Queue status">
      <span><strong>3</strong> open escalations</span>
      <span><strong>1</strong> needs evidence</span>
    </div>
  </header>

  <div class="workspace-grid">
    <nav class="panel queue-panel" aria-labelledby="refund-queue-title">
      <div class="panel-heading">
        <div class="panel-heading-row">
          <div>
            <p class="section-kicker">Current work</p>
            <h2 id="refund-queue-title">Refund queue</h2>
            <p class="helper-copy">Choose a request to review.</p>
          </div>
          <span class="queue-count">3 open</span>
        </div>
        <div class="queue-control">
          <label for="queue-order">Queue order</label>
          <select id="queue-order" name="queue-order">
            <option selected>Needs attention</option>
            <option>Highest amount</option>
          </select>
        </div>
      </div>

      <ol class="case-list">
        <li>
          <button class="case-card" type="button" aria-current="true">
            <span class="case-topline">
              <span class="case-id">R-1842</span>
              <span class="case-amount">$184.20</span>
            </span>
            <span class="case-name-row">
              <span class="case-customer">Nora Diaz</span>
              <span class="selected-label">Selected</span>
            </span>
            <span class="case-state">Needs receipt</span>
          </button>
        </li>
        <li>
          <button class="case-card" type="button">
            <span class="case-topline">
              <span class="case-id">R-1843</span>
              <span class="case-amount">$89.00</span>
            </span>
            <span class="case-customer">Jun Park</span>
            <span class="case-state">Policy question</span>
          </button>
        </li>
        <li>
          <button class="case-card" type="button">
            <span class="case-topline">
              <span class="case-id">R-1844</span>
              <span class="case-amount">$312.75</span>
            </span>
            <span class="case-customer">Amara Blake</span>
            <span class="case-state">Manager review</span>
          </button>
        </li>
      </ol>

      <div class="state-message empty-state" role="status">
        <strong>No refund escalations</strong>
        <span>New requests will appear here.</span>
      </div>
      <div class="state-message loading-state" role="status">
        <strong>Loading refund escalations</strong>
        <span>The queue is being refreshed.</span>
      </div>
      <div class="state-message error-state" role="alert">
        <strong>Refund queue unavailable</strong>
        <span>Try again before making a decision.</span>
      </div>
    </nav>

    <article class="panel review-panel" aria-labelledby="selected-request-title">
      <div class="selected-request">
        <div class="selected-heading-row">
          <div>
            <p class="section-kicker">Selected request</p>
            <h2 id="selected-request-title">R-1842 · Nora Diaz</h2>
            <p>Subscription renewal disputed after agent escalation.</p>
          </div>
          <span class="status-badge">Evidence incomplete</span>
        </div>

        <dl class="metadata">
          <div>
            <dt>Plan</dt>
            <dd>Pro annual</dd>
          </div>
          <div>
            <dt>Refund amount</dt>
            <dd>$184.20</dd>
          </div>
          <div class="request-summary">
            <dt>Customer request</dt>
            <dd>Review the disputed renewal and determine the next refund path.</dd>
          </div>
        </dl>

        <section class="content-section" aria-labelledby="evidence-title">
          <div class="section-heading-row">
            <div>
              <p class="section-kicker">What is available</p>
              <h3 id="evidence-title">Evidence checklist</h3>
            </div>
            <span class="evidence-count">2 of 3 confirmed</span>
          </div>

          <ul class="evidence-list">
            <li class="evidence-item" data-evidence="present">
              <span class="evidence-status">Confirmed</span>
              <div>
                <strong>Renewal date</strong>
                <p>Confirmed in purchase history.</p>
              </div>
            </li>
            <li class="evidence-item" data-evidence="present">
              <span class="evidence-status">Confirmed</span>
              <div>
                <strong>Refund reason</strong>
                <p>The support note captures the customer’s reason.</p>
              </div>
            </li>
            <li class="evidence-item" data-evidence="missing">
              <span class="evidence-status">Missing</span>
              <div>
                <strong>Receipt photo</strong>
                <p>Needed before manager approval.</p>
              </div>
            </li>
          </ul>
        </section>

        <section class="content-section" aria-labelledby="policy-title">
          <div class="policy-block">
            <p class="section-kicker">Policy context</p>
            <h3 id="policy-title">Inside the exception window</h3>
            <p>Manager approval is allowed when evidence is complete.</p>
            <p>Send unclear duplicate-charge cases to policy review.</p>
          </div>
        </section>
      </div>
    </article>

    <section class="panel decision-panel" aria-labelledby="decision-title">
      <div class="panel-heading">
        <p class="section-kicker">Next path</p>
        <h2 id="decision-title">Decision and handoff</h2>
        <p class="helper-copy">Choose the path supported by the current evidence.</p>
      </div>

      <div class="decision-body">
        <div class="decision-group" role="group" aria-labelledby="decision-options-title" aria-describedby="decision-options-help">
          <div>
            <h3 id="decision-options-title">Decision path</h3>
            <p class="helper-copy" id="decision-options-help">Choose one path. The handoff will follow this decision.</p>
          </div>

          <button class="decision-choice" type="button" aria-pressed="false" disabled>
            <span class="choice-title">Approve refund</span>
            <span class="choice-description">Unavailable until the receipt photo is attached.</span>
          </button>

          <button class="decision-choice" type="button" aria-pressed="false">
            <span class="choice-title">Send to policy review</span>
            <span class="choice-description">Use when policy interpretation is still unclear.</span>
          </button>

          <button class="decision-choice" type="button" aria-pressed="true">
            <span class="choice-title-row">
              <span class="choice-title">Return for evidence</span>
              <span class="choice-selected">Selected</span>
            </span>
            <span class="choice-description">Ask the support agent to collect the missing receipt photo.</span>
          </button>
        </div>

        <section class="handoff-section" aria-labelledby="handoff-title">
          <h2 id="handoff-title">Handoff</h2>
          <p class="handoff-intro">Send the chosen path and a clear reason to the next owner.</p>

          <form class="handoff-form">
            <div class="control-block">
              <label for="next-owner">Next owner</label>
              <select id="next-owner" name="next-owner" required>
                <option selected>Support agent</option>
                <option>Policy team</option>
                <option>Support operations manager</option>
              </select>
            </div>

            <div class="control-block">
              <label for="handoff-reason">Reason for the decision</label>
              <textarea id="handoff-reason" name="handoff-reason" rows="4" required aria-describedby="handoff-reason-help">Receipt photo is missing. Ask the customer to attach proof before approval.</textarea>
              <p class="control-help" id="handoff-reason-help">Tell the next owner exactly what to collect or review.</p>
            </div>

            <div class="handoff-ready" role="status">
              <strong>Ready to send</strong>
              <span>Support agent will receive the selected path and reason.</span>
            </div>

            <button class="send-button" type="submit">Send handoff</button>
          </form>
        </section>
      </div>
    </section>
  </div>
</main>"}
